# Small wrist/foot pair names: semantic cross-check only, never an exact footprint claim.
pairs={
 'Ulnotriquetral':'ulna triquetrum','Ulnopisiform':'ulna pisiform','Ulnolunate':'ulna lunate','Ulnocapitate':'ulna capitate','Triquetrohamate':'triquetrum hamate','Triquetrocapitate':'triquetrum capitate','Trapezoideocapitate':'trapezoid capitate','Trapeziotrapezoidal':'trapezium trapezoid','Scapholunate':'scaphoid lunate','Radiocapitate':'radius capitate','Scaphotrapeziotrapezoidal':'scaphoid trapezium trapezoid','Scaphocapitate':'scaphoid capitate','Radioscaphocapitate':'radius scaphoid capitate','Pisotriquetral':'pisiform triquetrum','Pisometacarpal':'pisiform metacarpal_5','Pisohamate':'pisiform hamate','scaphotriquetral':'scaphoid triquetrum','lunotriquetral':'lunate triquetrum','capitohamate':'capitate hamate','trapezoideocapitate':'trapezoid capitate','radio-ulnar':'radius ulna','cuboideonavicular':'cuboid navicular','cuneocuboid':'lateral_cuneiform cuboid'}
def complete_names(names):
 for name in names:
  if name in RULES:continue
  hit=next((bones for token,bones in pairs.items() if token.lower() in name.lower()),None)
  if hit:add(name,hit,'按名称涉及骨对初筛，需进一步核对其掌/背/足底位置、真实附着及是否独立成束。','仅名称语义初筛；未逐项文献核对，不作为解剖通过')
  else:add(name,'','源名可能表示一组连接。需逐个明确骨、软组织及分束；本轮不推定精确起止点。','信息结构已核查，具体解剖连接仍待专门参考')
